Definition dl_frame (s2 s1 s0 ra : word) : list cell := [C8 s2; C8 s1; C8 s0; C8 ra].

Definition adl_seg1_post (ra sp gp tp a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (t0 t1 t2 t3 t4 t5 t6 s0 s1 : word) (Fa first lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1v m',
    ms' = MS (mkR ra (wz (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz (Fa + 32)) (wz ASHADOW_BASE) (wz first) a1v a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz (if first =? Fa + 32 then ADL_EXIT else ADL_LOOP)) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp + -32, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -32)
    /\ rw_cells asegs m' (bv_unsigned sp + -32) (dl_frame s2 s1 s0 ra).
