(* [comment removed for export] *)
Lemma adl_latch : forall (pcv rav sp gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (hL nxt : Z),
  0 <= hL < 2^64 -> 0 <= nxt < 2^64 -> mem_inv asegs m ->
  (pcv = wz ADL_RA \/ pcv = ret_pc (wz ADL_RA)) ->
  evt asegs (fun ms' => ms' = MS (mkR rav sp gp tp t0 t1 t2 (wz hL) s1 (wz nxt) a1 a2 a3 a4 a5 a6 a7 (wz nxt) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                            F (wz (if nxt =? hL then ADL_EXIT else ADL_LOOP)) fc None m (seg_rom asegs))
    (MS (mkR rav sp gp tp t0 t1 t2 (wz hL) s1 a0 a1 a2 a3 a4 a5 a6 a7 (wz nxt) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
