(* [comment removed for export] *)
Definition adl_rem (m : mem) (LBc : list block) (hL : Z) (bs : list block) (em : gmap Z elt) : Prop :=
  forall A b B, bs = A ++ b :: B ->
    In b LBc /\ exists d (wprev : word) nd pad, em !! (blk_addr b) = Some d /\ blk_size b = esize d
      /\ rw_cells asegs m (blk_addr b) [C8 (wz (lhead hL (map blk_addr B))); C8 wprev]
      /\ rw_cells asegs m (blk_addr b + 16) (NodeCells nd pad)
      /\ rw_cells asegs m (blk_addr b + 48) (ValCells d)
      /\ addressable m (blk_addr b) (esize d).

(* [comment removed for export] *)
Fixpoint bcost (H : asr) (bs : list block) : Z :=
  match bs with [] => 0 | b :: bs' => as_Cf H (blk_size b) + bcost H bs' end.

(* [comment removed for export] *)
Lemma elt_blob : forall m x nxt (wprev : word) nd pad d,
  rw_cells asegs m x [C8 (wz nxt); C8 wprev] -> rw_cells asegs m (x + 16) (NodeCells nd pad) -> rw_cells asegs m (x + 48) (ValCells d) ->
  exists bs, rw_cells asegs m x [CB (Z.to_nat (esize d)) bs].
Proof.
  intros m x nxt wprev nd pad d LN ND PL. pose proof (esize_ge d) as EG.
  assert (C : rw_cells asegs m x (([C8 (wz nxt); C8 wprev] ++ NodeCells nd pad) ++ ValCells d)).
  { apply rw_cells_app. split.
    - apply rw_cells_app. split; [exact LN|]. cbn [cells_size csize Nat.add]. replace (x + Z.of_nat 16) with (x + 16) by lia. exact ND.
    - rewrite cells_size_app, NodeCells_size. cbn [cells_size csize Nat.add]. replace (x + Z.of_nat 48) with (x + 48) by lia. exact PL. }
  destruct (rw_cells_forget _ _ _ _ C) as [junk K]. exists junk.
  rewrite !cells_size_app, NodeCells_size in K. cbn [cells_size csize Nat.add] in K.
  pose proof (ValCells_size d) as VS.
  replace (Z.to_nat (esize d)) with (16 + 32 + cells_size (ValCells d))%nat by lia. exact K.
Qed.

Section W.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis ATR : incl TRLIST (as_TR H).      (* [comment removed for export] *)

  (* [comment removed for export] *)
  Lemma ablk_same : forall s LB m b1 b2, as_RHEAP H s LB m -> In b1 LB -> In b2 LB -> blk_addr b1 = blk_addr b2 -> b1 = b2.
  Proof.
    intros s LB m b1 b2 HP I1 I2 E. destruct (bptr_eq_dec (blk_id b1) (blk_id b2)) as [Ei|NE].
    - exact (nodup_blk_eq LB _ _ (ah_nodup H HH _ _ _ HP) I1 I2 Ei).
    - exfalso. pose proof (ah_blocks H HH _ _ _ _ HP I1) as (_ & _ & K1 & _). pose proof (ah_blocks H HH _ _ _ _ HP I2) as (_ & _ & K2 & _).
      destruct (ah_disj H HH _ _ _ _ _ HP I1 I2 NE); lia.
  Qed.

  Lemma bcost_nonneg : forall s LB m bs, as_RHEAP H s LB m -> (forall b, In b bs -> In b LB) -> 0 <= bcost H bs.
  Proof.
    intros s LB m bs HP. pose proof (ah_costs H HH) as (_ & _ & CF0 & _). induction bs as [|c bs IH]; intros SUB; cbn; [lia|].
    pose proof (ah_blocks H HH _ _ _ c HP (SUB c (or_introl eq_refl))) as (_ & _ & K3 & _).
    specialize (IH ltac:(intros b Hb; apply SUB; right; exact Hb)). pose proof (CF0 _ K3). lia.
  Qed.

  (* [comment removed for export] *)
  Definition adlI_post (sp gp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LBc : list block) (LF : list fframe) (hL lo B shi : Z) (b : block) (R : list block) (em : gmap Z elt) (errv : word)
      (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : as_St H),
      let nxt := lhead hL (map blk_addr R) in
      let LB1 := as_lb_remove H (blk_id b) LBc in
      as_VIS H s' (cfg_ms c) = MS (mkR (wz ADL_RA) (wz (bv_unsigned sp + -32)) gp (wz ATP) t0 t1 t2 (wz hL) (wz ASHADOW_BASE) (wz nxt) a1 a2 a3 a4 a5 a6 a7
                                       (wz nxt) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                  F (wz (if nxt =? hL then ADL_EXIT else ADL_LOOP)) fc None m' (seg_rom asegs)
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells asegs m' AERRNO [C4 errv] /\ as_rauxv_ok H m' B
      /\ as_RHEAP H s' LB1 m'
      /\ apres H LB1 (bv_unsigned sp + -32) m m'
      /\ adl_rem m' LB1 hL R em
      /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
      /\ as_AL H s' >= as_AL H s - as_Cf H (blk_size b).
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.prod Sort Prop.
Scheme kc__6 := Elimination for LinuxProcessSemantics.LinuxProcessSem.Run.config Sort Prop.
Scheme kc__7 := Elimination for Corelib.Init.Datatypes.list Sort Prop.

  Lemma adl_iter : forall (rax s2x sp gp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
      (F : bvmap 5 word) (fc : bv 32) (msF : machine_state) (m : mem) (mo : Model) (s : as_St H) (LBc : list block) (LF : list fframe)
      (hL lo B shi : Z) (b : block) (R : list block) (em : gmap Z elt) (errv : word),
    as_VIS H s msF = MS (mkR rax (wz (bv_unsigned sp + -32)) gp (wz ATP) t0 t1 t2 (wz hL) (wz ASHADOW_BASE) (wz (blk_addr b)) a1 a2 a3 a4 a5 a6 a7
                             s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                        F (wz ADL_LOOP) fc None m (seg_rom asegs) ->
    adl_rem m LBc hL (b :: R) em -> List.NoDup (map blk_id (b :: R)) -> em_ok em ->
    0 <= hL -> hL + 16 <= aceil ->
    as_RHEAP H s LBc m -> as_AKREL H s (mkCfg msF mo) ->
    as_rauxv_ok H m B -> bv_unsigned sp <= B ->
    stk asegs m lo (bv_unsigned sp + -32) -> aceil <= lo -> lo <= bv_unsigned sp - ADELETE_LIST_STACK ->
    rw_cells asegs m AERRNO [C4 errv] -> mem_inv asegs m -> bv_unsigned sp mod 16 = 0 ->
    as_RFS H LF m -> ACONST m -> stack0 m lo shi ->
    as_Cf H (blk_size b) <= as_AL H s ->
