  (* [comment removed for export] *)
  Definition adl_loop_post (sp gp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LBc : list block) (LF : list fframe) (hL lo B shi : Z) (bs : list block) (errv : word) (m : mem) (mo : Model)
      : config -> Prop :=
    fun c => exists s2x t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : as_St H) (LB' : list block),
      as_VIS H s' (cfg_ms c) = MS (mkR (wz ADL_RA) (wz (bv_unsigned sp + -32)) gp (wz ATP) t0 t1 t2 (wz hL) (wz ASHADOW_BASE) a0 a1 a2 a3 a4 a5 a6 a7
                                       s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                  F (wz ADL_EXIT) fc None m' (seg_rom asegs)
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells asegs m' AERRNO [C4 errv] /\ as_rauxv_ok H m' B
      /\ as_RHEAP H s' LB' m'
      /\ (forall b', In b' LB' <-> (In b' LBc /\ ~ In (blk_id b') (map blk_id bs)))
      /\ lb_bytes LB' + lb_bytes bs = lb_bytes LBc /\ (length LB' + length bs = length LBc)%nat
      /\ xpres H LB' (bv_unsigned sp + -32) [] m m'
      /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
      /\ as_AL H s' >= as_AL H s - bcost H bs.

  Lemma adl_loop : forall (R : list block) (b : block)
      (rax s2x sp gp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
      (F : bvmap 5 word) (fc : bv 32) (msF : machine_state) (m : mem) (mo : Model) (s : as_St H) (LBc : list block) (LF : list fframe)
      (hL lo B shi : Z) (em : gmap Z elt) (errv : word),
    as_VIS H s msF = MS (mkR rax (wz (bv_unsigned sp + -32)) gp (wz ATP) t0 t1 t2 (wz hL) (wz ASHADOW_BASE) (wz (blk_addr b)) a1 a2 a3 a4 a5 a6 a7
                             s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                        F (wz ADL_LOOP) fc None m (seg_rom asegs) ->
    adl_rem m LBc hL (b :: R) em -> List.NoDup (map blk_id (b :: R)) -> em_ok em -> (forall e d, em !! e = Some d -> e <> hL) ->
    0 <= hL -> hL + 16 <= aceil ->
    as_RHEAP H s LBc m -> as_AKREL H s (mkCfg msF mo) ->
    as_rauxv_ok H m B -> bv_unsigned sp <= B ->
    stk asegs m lo (bv_unsigned sp + -32) -> aceil <= lo -> lo <= bv_unsigned sp - ADELETE_LIST_STACK ->
    rw_cells asegs m AERRNO [C4 errv] -> mem_inv asegs m -> bv_unsigned sp mod 16 = 0 ->
    as_RFS H LF m -> ACONST m -> stack0 m lo shi ->
    bcost H (b :: R) <= as_AL H s ->
    as_SR H (adl_loop_post sp gp s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LBc LF hL lo B shi (b :: R) errv m mo) (mkCfg msF mo).
