  (* [comment removed for export] *)
  Lemma adl_rem_intro : forall s m LB Fa S L ns ls em,
    AFieldsC m Fa S L ns ls em -> AFieldsOwn LB em -> as_RHEAP H s LB m ->
    exists bs, map blk_addr bs = L /\ adl_rem m LB (Fa + 32) bs em /\ List.NoDup (map blk_id bs)
               /\ (forall b, In b bs -> In b LB /\ afowned em b).
  Proof.
    intros s m LB Fa S L ns ls em FC OWN HP.
    pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
    pose proof (dl_N _ _ _ DL) as ND0.
    assert (G : forall L2 L1, L = L1 ++ L2 ->
      exists bs, map blk_addr bs = L2 /\ adl_rem m LB (Fa + 32) bs em /\ List.NoDup (map blk_id bs)
                 /\ (forall b, In b bs -> In b LB /\ afowned em b)).
    { induction L2 as [|y L2 IH]; intros L1 EL.
      - exists []. split; [reflexivity|]. split; [intros A b B E; destruct A; discriminate|]. split; [constructor|]. intros b [].
      - destruct (IH (L1 ++ [y]) ltac:(rewrite EL, <- app_assoc; reflexivity)) as (bs' & MAP & REM & ND & SUB).
        assert (INy : y ∈ L). { rewrite EL. rewrite elem_of_app, elem_of_cons. right; left; reflexivity. }
        pose proof (proj1 (LE y) INy) as Ky. destruct (em !! y) as [d|] eqn:Ld; [| exfalso; exact (is_Some_None Ky)].
        destruct (OWN y d Ld) as [p [INp SZ]].
        exists ((p, y, esize d) :: bs'). split; [cbn; rewrite MAP; reflexivity|]. split.
        { intros A b B E. destruct A as [|a A'].
          - cbn in E. injection E as <- <-. cbn [blk_addr blk_size fst snd]. split; [exact INp|].
            destruct (mb_lnode m _ _ _ y DL LC ltac:(rewrite elem_of_cons; right; exact INy)) as (nd & _ & _ & _ & C).
            destruct (AFieldsC_L_node _ _ _ _ _ _ _ _ FC INy) as (tn & pad & _ & _ & TN).
            exists d, (wz (cprev (Fa + 32) L y)), tn, pad. split; [exact Ld|]. split; [reflexivity|]. split; [| split; [exact TN| split; [exact (EC _ _ Ld)| exact (ESH _ _ Ld)]]].
            rewrite MAP. replace (cnext (Fa + 32) L y) with (lhead (Fa + 32) L2) in C; [exact C|].
            symmetry. rewrite EL. apply cnext_at. rewrite <- EL. exact (nd_cons_tl _ _ ND0).
          - cbn in E. injection E as Ea E'. exact (REM A' b B E'). }
        split.
        { cbn. constructor; [| exact ND]. intros K. apply in_map_iff in K. destruct K as (b' & Eb' & Hb').
          destruct (SUB b' Hb') as [INb' _].
          assert (Eq : b' = (p, y, esize d)) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ HP)| exact INb'| exact INp| exact Eb']).
          subst b'. assert (Iy : In y (map blk_addr bs')) by (apply in_map_iff; exists (p, y, esize d); split; [reflexivity| exact Hb']).
          rewrite MAP in Iy. rewrite EL in ND0.
          pose proof (nd_cons_tl _ _ (nd_cons_tl _ _ ND0)) as NDL. apply list.NoDup_app in NDL. destruct NDL as (_ & _ & NDL).
          apply list.NoDup_cons in NDL. destruct NDL as [NI _]. apply NI. apply list_elem_of_In. exact Iy. }
        intros b [<-|Hb]; [| exact (SUB b Hb)]. split; [exact INp|]. exists d. cbn [blk_addr blk_size fst snd]. split; [exact Ld| reflexivity]. }
    exact (G L [] eq_refl).
  Qed.

  (* [comment removed for export] *)
  Lemma afowned_ids : forall s LB m bs L em,
    as_RHEAP H s LB m -> (forall b, In b bs -> In b LB /\ afowned em b) -> map blk_addr bs = L ->
    (forall e, e ∈ L <-> is_Some (em !! e)) ->
    forall b', In b' LB -> (In (blk_id b') (map blk_id bs) <-> afowned em b').
  Proof.
    intros s LB m bs L em HP SUB MAP LE b' Hb'. split.
    - intros K. apply in_map_iff in K. destruct K as (b & Eb & Hb). destruct (SUB b Hb) as [INb Fb].
      assert (b' = b) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ HP)| exact Hb'| exact INb| symmetry; exact Eb]).
      subst b'. exact Fb.
    - intros (d & Ld & SZ).
      assert (IL : blk_addr b' ∈ L). { apply LE. rewrite Ld. eexists; reflexivity. }
      rewrite <- MAP in IL. apply list_elem_of_In in IL. apply in_map_iff in IL. destruct IL as (b & Eb & Hb).
      destruct (SUB b Hb) as [INb _].
      assert (b = b') by (eapply ablk_same; [exact HP| exact INb| exact Hb'| exact Eb]).
      subst b. apply in_map. exact Hb.
  Qed.

  (* [comment removed for export] *)
  Lemma bcost_dl_cost : forall bs L em,
    map blk_addr bs = L -> (forall b, In b bs -> afowned em b) -> bcost H bs = dl_cost H L em.
  Proof.
    induction bs as [|[[p x] n] bs IH]; intros L em MAP OWN; cbn in MAP; subst L; cbn; [reflexivity|].
    destruct (OWN (p, x, n) (or_introl eq_refl)) as (d & Ld & SZ). cbn [blk_addr blk_size fst snd] in Ld, SZ. rewrite Ld, SZ.
    rewrite (IH _ em eq_refl ltac:(intros b Hb; apply OWN; right; exact Hb)). reflexivity.
  Qed.

